  Mark2         DECIMAL(5,2) DEFAULT 0.00 NOT NULL,  -- العلامة 2
  Mark3         DECIMAL(5,2) DEFAULT 0.00 NOT NULL,  -- العلامة 3
  Mark4         DECIMAL(5,2) DEFAULT 0.00 NOT NULL,  -- العلامة 4
  Mark5         DECIMAL(5,2) DEFAULT 0.00 NOT NULL,  -- العلامة 5
  Rem           VARCHAR(100),                  -- ملاحظات
